/* Booking PINs are 4 digits (1000-9999). Used for open-play joins (which
   have no customer-typed PIN) and for the staff reset in renderAdminBookings. */
function generateBookingPin(){
  const n = (window.crypto && crypto.getRandomValues) ? crypto.getRandomValues(new Uint32Array(1))[0] : Math.floor(Math.random() * 0x100000000);
  return String(1000 + (n % 9000));
}
