/* ----------------------------------------------------------------
   Core-listener error signal. Each core onSnapshot below (bookings,
   openPlay, staffReserve, pricing, courtHours, settings, queues,
   courts) previously swallowed failures with a console.warn only --
   a permission-denied or network-loss failure was invisible to the
   user. Track which named listeners currently have an outstanding
   error and surface one small, non-blocking, honest banner (never a
   blocking alert()) describing the likely cause. Cleared per-listener
   the moment that listener's handler runs successfully again.
   ---------------------------------------------------------------- */
window._listenerErrors = window._listenerErrors || new Map();
function _classifyFirestoreError(e) {
  if (!navigator.onLine) return 'offline';
  if (e && e.code === 'permission-denied') return 'permission';
  if (e && (e.code === 'unavailable' || e.code === 'deadline-exceeded' || e.code === 'cancelled')) return 'network';
  return 'unknown';
}
function renderListenerErrorBar() {
  const bar = document.getElementById('dataSyncErrorBar');
  if (!bar) return;
  // The offline bar already explains a plain "no network" state -- don't pile on.
  if (!navigator.onLine || window._listenerErrors.size === 0) {
    bar.style.display = 'none';
    bar.classList.add('hidden');
    return;
  }
  const kinds = new Set(Array.from(window._listenerErrors.values()).map(v => v.kind));
  let msg;
  if (kinds.has('permission')) {
    msg = '⚠ Permission error loading live data — try refreshing or signing in again.';
  } else if (kinds.has('network')) {
    msg = '⚠ Connection trouble — some data may be out of date.';
  } else {
    msg = '⚠ Live updates are having trouble syncing — some changes may not appear yet.';
  }
  bar.textContent = msg;
  bar.style.display = '';
  bar.classList.remove('hidden');
}
function setListenerError(name, e) {
  console.warn(name + ' listener:', e && e.message);
  window._listenerErrors.set(name, { kind: _classifyFirestoreError(e), message: e && e.message });
  renderListenerErrorBar();
}
function clearListenerError(name) {
  if (window._listenerErrors.delete(name)) renderListenerErrorBar();
}
window.addEventListener('online', renderListenerErrorBar);
window.addEventListener('offline', renderListenerErrorBar);

