/* ---------- Booking PIN gate: attempt tracking + brief cooldown ----------
   The pay-pending / cancel-booking PIN prompts below used to just
   alert('Incorrect Booking PIN!') in an infinite bare loop. The state
   machine (attempt counting + cooldown window) is pure logic in
   pin-gate.js (PinGate) so it's unit-testable; this is just the DOM-side
   prompt()/alert() wiring around it, one independent record per
   booking+action key so a wrong guess on one booking never penalizes
   another. This is a walk-in booking PIN, not a security-critical
   account, so a short cooldown is enough -- not a permanent lockout. */
const _bookingPinRecords = new Map();
function tryBookingPinGate(key){
  const check = PinGate.checkGate(_bookingPinRecords.get(key), Date.now());
  _bookingPinRecords.set(key, check.record);
  if(check.blocked){
    alert(`Too many incorrect PIN attempts. Please wait ${check.secondsLeft}s before trying again.`);
    return false;
  }
  return true;
}
function reportBookingPinResult(key, correct){
  const result = PinGate.recordResult(_bookingPinRecords.get(key), correct, { nowMs: Date.now() });
  _bookingPinRecords.set(key, result.record);
  if(result.outcome === 'cooldown'){
    alert(`Incorrect Booking PIN. Too many wrong attempts -- please wait ${result.cooldownSeconds}s before trying again.`);
  } else if(result.outcome === 'wrong'){
    alert(`Incorrect Booking PIN! (${result.attemptsLeft} attempt${result.attemptsLeft === 1 ? '' : 's'} left before a short cooldown)`);
  }
}

