/* ---------- Load-screen timeout ----------
   initializeApp() awaits loadClientConfig()+loadTenantStatus() with no
   client-side timeout, so #loadingScreen never gets a fallback if that
   hangs (e.g. a very slow or stalled connection). Show a "taking longer
   than expected" message with a Retry button INSIDE the existing
   loading screen after LOAD_TIMEOUT_MS -- the spinner/text stay, this
   only augments it. If the load finishes first, the timer is cleared
   and this never shows. */
const LOAD_TIMEOUT_MS = 10000;
let _loadTimeoutTimer = null;
function armLoadTimeout() {
  clearTimeout(_loadTimeoutTimer);
  _loadTimeoutTimer = setTimeout(showLoadTimeoutMessage, LOAD_TIMEOUT_MS);
}
function disarmLoadTimeout() {
  clearTimeout(_loadTimeoutTimer);
  _loadTimeoutTimer = null;
}
function showLoadTimeoutMessage() {
  const msg = document.getElementById('loadingTimeoutMsg');
  if (msg) msg.style.display = 'block';
}
document.getElementById('loadingTimeoutRetryBtn')?.addEventListener('click', () => location.reload());

